window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-psych|xl-05|知识点四|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 3, "q": "关于操作技能的熟练阶段的特点，以下表述不正确的是（　）", "opts": ["完善化", "自动化", "系统化", "外显化"], "a": 3, "exp": "此题考查冯忠良的四阶段模型。依据知识点四第2题解析可知，D选项外显化是操作技能的模仿阶段的特点，即个体实际再现出特定的动作或行为模式。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-05|知识点四|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 4, "q": "在学习跳舞时，学习者大部分的注意力集中在观察教师的动作，一到自已做时动作就会不协调，还会产生相互干扰。说明此时学习者的操作技能处于的发展阶段为（　）", "opts": ["操作定向", "操作模仿", "操作整合", "操作熟练"], "a": 1, "exp": "此题考查冯忠良的四阶段模型。在操作技能的模仿阶段，学习者动作的稳定性、准确性、灵活性较差，各个动作要素之间的协调性也不如意，各要素相互干扰，个体动作主要靠视觉控制。这与题干中的表述相契合。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-05|知识点四|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 5, "q": "在动作技能的学习中，为了让学生形成正确的动作映象，下列说法中错误的是（　）", "opts": ["动作示范与言语解释相结合", "整体示范和分解示范相结合", "每次示范需要将完整的动作展现给学生", "指导学生观察，并纠正学生的错误理解"], "a": 2, "exp": "此题考查动作技能的学习。C选项中，在学生练习所学技能之前或练习过程中，教师应通过充分而准确的示范帮助他们在头脑中形成正确的动作映象。需要注意的是，在整个示范过程中，教师要防止学生的认知负荷超载，每次示范的信息量和速度要切合学生的实际水平，每次示范不需要将完整的动作展现给学生。此题为选非题，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-05|知识点四|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 6, "q": "教师在教学生游泳时，告诉学生正确的动作对应的肌肉会有什么样的感觉，这给学生的练习提供了（　）", "opts": ["结果反馈", "情境反馈", "分情况反馈", "内在的动觉反馈"], "a": 3, "exp": "此题考查操作技能的训练要求。A.结果反馈：在技能的练习中，教师让学生及时地了解自已的练习结果，有利于练习效率的提高。B.情境反馈：指出学生在真实情境中练习技能所出现的问题。C.分情况反馈：在技能形成的不同阶段，教师要给学生提供不同类型的反馈。D.内在的动觉反馈：教师应促进学生用对动作的动觉控制替代视觉控制，建立运动与肌肉之间的联系，增强学生内在反馈的作用，提高学生对各种肌肉动作的自我调节能力和控制能力。题干中的表述是让学生建立运动与肌肉之间的联系，属于内在的动觉反馈。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-05|知识点四|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 7, "q": "“见者易，学者难”，这句话说的是在操作技能学习中要强调（（　）", "opts": ["练习", "示范", "联系", "言语指导"], "a": 0, "exp": "此题考查操作技能的训练要求。“见”指观察别人执行动作技能，相当于示范。“学”则指观察后的模仿和练习。“见者易，学者难”强调的是“学”，即练习的重要性。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-05|知识点四|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 8, "q": "小明在练习百米赛跑，几个月之后，虽然还在不断练习，但是跑步成绩却不再提高，这说明小明在练习中出现了（　）", "opts": ["浮动现象", "起伏现象", "差异现象", "高原现象"], "a": 3, "exp": "此题考查练习中的相关现象。A.浮动现象：一般指成绩在一定范围内小幅上下波动，并非长期停滞不前，不符合题意。B.起伏现象：在练习中学生的成绩时而提高、时而下降、时而停顿的现象。C.差异现象：不同的学生在学习同一技能，或同一个学生在学习不同技能时，其练习进程表现出明显的个体差异。D.高原现象：在学生动作技能的形成过程中，练习到一定阶段往往出现进步暂时停顿的现象。题干中小明在几个月的练习之后跑步成绩不再提高，是出现了高原现象。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}},
  {"id": "kc|edu-psych|xl-06|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点一：学习策略", "no": 1, "q": "以下不属于学习策略的特征的是（　）", "opts": ["主动性", "有效性", "程序性", "相似性"], "a": 3, "exp": "此题考查学习策略的特征。学习策略的特征有主动性、有效性、过程性、程序性。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点二：认知策略概述", "no": 1, "q": "下列各种学习策略中，都属于认知策略的是（…（　）", "opts": ["注意策略、调节策略、复述策略、精细加工策略", "注意策略、精细加工策略、复述策略、组织策略", "注意策略、精细加工策略、组织策略、计划策略", "监控策略、精细加工策略、复述策略、组织策略"], "a": 1, "exp": "此题考查认知策略的分类。认知策略包括注意策略、精细加工策略、复述策略和组织策略；调节策略、计划策略和监控策略属于元认知策略。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点二：认知策略概述", "no": 2, "q": "以下情况中，属于认知策略的是（　）", "opts": ["学生看书的时候碰到不会的单词就查字典", "为了记住要点，看书时标记关键词", "学完功课时自己进行测验", "为了提高效率，选择在图书馆这样安静的地方学习"], "a": 1, "exp": "此题考查认知策略的含义。认知策略是学习过程中为了提高学习效率而采取的措施。A选项属于资源管理策略中的学业求助策略；C选项属于对学习的管理，是元认知策略；D选项是资源管理策略。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点二：认知策略概述", "no": 3, "q": "下列不属于认知策略的是（　）", "opts": ["根据句法属性或语义对概念和词等进行分类", "通过使用例子来总结规则", "运用数字、符号、缩写、关键词等记录和储存信息", "分清任务的轻重缓急"], "a": 3, "exp": "此题考查认知策略。A选项属于认知策略中的组织策略；B选项属于认知策略中的精细加工策略；C选项属于认知策略中的复述策略和精细加工策略；D选项属于资源管理策略中的时间管理策略。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点二：认知策略概述", "no": 4, "q": "小华在复习历史时，将秦始皇统一六国的时间（公元前221年）与自己家的门牌号“221”联系起来，从而轻松记住了这一年份。这种学习方法属于（　）", "opts": ["复述策略", "组织策略", "精细加工策略", "注意策略"], "a": 2, "exp": "此题考查精细加工策略。A.复述策略：单纯重复信息（如反复背诵“公元前221年，秦始皇统一六国”），不涉及意义加工。B.组织策略：整理信息结构（如画时间轴、做分类表格），未体现信息之间的意义联系。C.精细加工策略：通过赋予意义、建立联系的方式加深记忆（如联想、类比、举例）。题干中，将抽象的年份（公元前221年）与熟悉的门牌号（221）关联，属于典型的意义联想。√D.注意策略：题干讲的是记忆方法，不是说个体注意到了信息。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点三：注意策略与精细加工策略", "no": 1, "q": "下列不属于注意策略的是（　）", "opts": ["告知目标", "摘抄", "使用标示重点的线索", "增加材料的独特性"], "a": 1, "exp": "此题考查注意策略。注意策略指学习者在学习情境中激活与维持学习的心理状态，将注意力集中于有关学习信息或重要信息上，对学习材料保持高度觉醒和警觉状态的学习策略。（1）A、C、D选项中告知目标、使用标示重点的线索、增加材料的独特性都属于运用注意策略，帮助学习者将注意力集中于学习信息或重要信息上。（2）B选项摘抄是对材料中关键信息的提取、书写与巩固，属于复述策略或精细加工策略，侧重巩固记忆，而非引导注意。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 115}},
  {"id": "kc|edu-psych|xl-06|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点三：注意策略与精细加工策略", "no": 2, "q": "在学习过程中，学习者对学习的某些内容专门做批注，这种学习策略是（　）", "opts": ["编码与组织策略", "精细加工策略", "复述策略", "元认知策略"], "a": 1, "exp": "此题考查精细加工策略。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点三|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点三：注意策略与精细加工策略", "no": 3, "q": "在学习“医生讨厌律师”这句话时，我们附加一句“律师起诉了医生”，以后回忆就相对容易一些。这主要采用了（　）", "opts": ["精细加工策略", "注意策略", "组织策略", "复述策略"], "a": 0, "exp": "此题考查精细加工策略。认知策略总结表名称含义学习者在学习情境中激活与维持学习的心理状态，将注意力集中于有关学习信息或重要信息上，对注意策略学习材料保持高度觉醒和警觉状态的学习策略精细加工策略通过把所学的新信息和已有的知识联系起来以增加新信息意义的策略在工作记忆中为了保持信息，运用内部言语在大脑中重现学习材料或刺激，以便将注意力维持在学复述策略习材料之上的策略整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略，常用的组织策略有列组织策略提纲、做图解、做表格等依据认知策略总结表可知，题干中通过附加一句话，使以后的回忆相对容易一些，就是通过增加新信息意义来促进记忆的方式。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点三|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点三：注意策略与精细加工策略", "no": 4, "q": "地理老师教学生记忆“乞力马扎罗山”时，为方便学生记忆，将之戏称为“骑着马打着锣”。这种学习策略属于（　）", "opts": ["元认知策略", "精细加工策略", "资源管理策略", "组织策略"], "a": 1, "exp": "此题考查精细加工策略。依据认知策略总结表（知识点三第3题解析）可知，题干中，教师利用谐音帮助学生记忆“乞力马扎罗山”，将其与熟悉的形象“骑着马打着锣”联系起来，赋予“乞力马扎罗山”一定的意义，这是精细加工策略中的一种常见形式一谐音联想法。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点三|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点三：注意策略与精细加工策略", "no": 5, "q": "认知策略中有一种精细加工策略，以下不属于这一策略的是（　）", "opts": ["过度学习", "首字联词法", "关键词法", "视觉想象"], "a": 0, "exp": "此题考查精细加工策略。精细加工策略中的常用策略主要包括：（1）简单的精细加工策略，包括位置记忆法、首字联词法、限定词法（谐音联想法）、琴栓一单词法、关键词法、视觉想象。（2）复杂的精细加工策略，包括意义识记、主动应用、利用背景信息。由此可知，过度学习不属于精细加工策略，过度学习是复述策略的一种常用策略。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 1, "q": "后面所学的信息干扰了先前所学的信息在记忆中的保存，这种现象叫作（　）", "opts": ["前摄促进", "倒摄促进", "前摄抑制", "倒摄抑制"], "a": 3, "exp": "此题考查基本的记忆规律。A.前摄促进：学习某件事常常有助于以后学习类似的事。C.倒摄促进：后面所学的信息有助于先前信息的学习。B.前摄抑制：先前所学的信息干扰了后面信息的学习。D.倒摄抑制：后面所学的信息干扰了先前所学的信息在记忆中的保存，与题意相符。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 2, "q": "在记忆一篇较长的文章时，开头和结尾部分容易记住，中间部分容易遗忘，这是（）影响的结果。（　）", "opts": ["同化", "痕迹消退", "压抑", "前摄抑制与倒摄抑制"], "a": 3, "exp": "此题考查基本的记忆规律。依据知识点四第1题解析可知，中间部分容易遗忘是因为它同时受到了前面信息的前摄抑制和后面信息的倒摄抑制的双重干扰。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 3, "q": "有些教师一上课就检查家庭作业、点名等，其实这并不科学，最好还是一上课就开始介绍最基本的概念。这利用了学生学习的（　）", "opts": ["酝酿效应", "前测效应", "首因效应", "近因效应"], "a": 2, "exp": "此题考查基本的记忆规律。在记忆中，我们更倾向于记住最开始的事情和距离我们最近的事情，分别叫作首因效应和近因效应。根据首因效应，教师应当把重要的、最基本的概念学习放在一堂课的开始。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 4, "q": "根据过度学习，小明复述30分钟刚好可以背熟某篇英语作文。为了防止遗忘，他应当再复述这篇英语作文（　）", "opts": ["5分钟", "10分钟", "15分钟", "20分钟"], "a": 2, "exp": "此题考查过度学习。研究表明，150%的过度学习是最适宜的。已知小明刚好背熟某篇英语作文需要30分钟，那么达到150%的过度学习的总时长应为45分钟。他已经学习了30分钟，为了防止遗忘，他应当再复述这篇英语作文15分钟。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 5, "q": "随着学习的任务越来越少，学生学得越来越好，完成任务所需要的注意力也就越来越少。这一过程称为（　）", "opts": ["排除干扰", "自动化", "过度学习", "前摄促进"], "a": 1, "exp": "此题考查复述策略的常用策略。“随着学习的任务越来越少，学生学得越来越好，完成任务所需要的注意力也就越来越少”，这一过程属于自动化。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 6, "q": "下列不属于组织策略的是（　）", "opts": ["列提纲", "提问", "做流程图", "做表格"], "a": 1, "exp": "此题考查组织策略。依据认知策略总结表（知识点三第3题解析）可知，组织策略主要包括列提纲、做图解、做表格等。提问属于学业求助策略。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点四|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点四：复述策略与组织策略", "no": 7, "q": "下列学习活动中，最典型地运用了组织策略的是（　）", "opts": ["反复大声朗读课文三遍", "在历史事件旁边写下自己的感想", "画出一张“中国古代朝代更替时序图", "检查自己是否完成了今天的背诵任务"], "a": 2, "exp": "此题考查组织策略。A.反复大声朗读课文三遍：典型的复述策略（机械重复）。B.在历史事件旁写下自己的感想：典型的精细加工策略（增加个人感想）。C.画出一张“中国古代朝代更替时序图”：组织策略的经典表现，通过图形（时序图）对分散的知识点进行结构化、序列化的整理。√D.检查自已是否完成了今天的背诵任务：属于元认知策略中的监控调节。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点五|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点五：元认知策略及其教学", "no": 1, "q": "研究者在进行实验研究时，经常会自我反问：“我们是否按照已有计划进行问题解决？我们正逐步接近目标吗？哪些措施没有在实验中起作用？”该研究者运用的学习策略是（　）", "opts": ["精细加工策略", "组织策略", "努力管理策略", "元认知策略"], "a": 3, "exp": "此题考查元认知策略。A.精细加工策略：通过把所学的新信息和已有的知识联系起来以增加新信息意义的策略。B.组织策略：整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略。常用的组织策略有列提纲、做图解、做表格。C.努力管理策略：为了维持或促进意志努力，而对自己的学习兴趣、态度、情绪状态等心理因素进行约束和调整，实现学习目标的策略。D.元认知策略：对信息加工流程进行控制的策略，包括计划策略、监察策略（监控策略）和调节策略。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点五|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点五：元认知策略及其教学", "no": 2, "q": "当读者阅读一篇深奥难懂的文章时，会放慢阅读的速度。这种元认知策略是（　）", "opts": ["计划策略", "领会策略", "精细加工策略", "调节策略"], "a": 3, "exp": "此题考查元认知策略。A.计划策略：根据认知活动的特定目标，在一项认知活动之前计划各种活动、预计结果、选择策略，想出各种解决问题的方法，并预估其有效性。B.领会策略：不属于元认知策略的分类。C.精细加工策略：属于认知策略。D.调节策略：核查认知活动结果并采取相应的补救措施，核查认知策略的效果，并及时修正、调整认知策略。发现文章难懂则放慢阅读速度属于调节策略。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 116}},
  {"id": "kc|edu-psych|xl-06|知识点五|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点五：元认知策略及其教学", "no": 3, "q": "学生在解题过程中对题目浏览、测查、完成情况的监控及对速度的把握主要采用了（　）", "opts": ["认知策略", "元认知策略", "组织策略", "复述策略"], "a": 1, "exp": "此题考查元认知策略。元认知策略是对信息加工流程进行控制的策略，包括计划策略、监察策略（监控策略）和调节策略。题干中学生对知识加工过程的监控及对速度的把握属于元认知策略。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点五|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点五：元认知策略及其教学", "no": 4, "q": "下列选项中，属于是元认知策略的是（　）", "opts": ["学生考试后，能准确地预测自己的分数", "学生在学习中能举一反三", "学生能利用复述策略进行记忆", "学生阅读时，先总体浏览标题句，再阅读细节，最后读小结"], "a": 3, "exp": "此题考查元认知策略。A.学生考试后，能准确地预测自已的分数：这是对考试结果的主观判断，未涉及认知过程中的监控、调节。B.学生在学习中能举一反三：这体现的是迁移能力，属于认知能力范畴，而非对认知过程的调控。C.学生能利用复述策略进行记忆：复述策略属于认知策略，并非元认知策略。D.学生在阅读前，主动规划了自已的学习步骤（先浏览一再细读一最后总结）。这体现了元认知策略中的计划策略。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点六|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点六：资源管理策略及其教学", "no": 1, "q": "将一天的事情按照重要和紧急程度进行排序，属于（　）", "opts": ["时间管理策略", "调节策略", "认知策略", "精细加工策略"], "a": 0, "exp": "此题考查时间管理策略。时间管理策略是通过一定的方法合理安排时间、有效利用学习资源的策略。“将事情按照重要和紧急程度进行排序”属于对时间的规划与安排，高效率利用时间。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点六|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点六：资源管理策略及其教学", "no": 2, "q": "小红认为自已在晚上的记忆效果更好，因此她将侧重记忆的内容安排在晚上学习。她用到的学习策略是（　）", "opts": ["计划策略", "时间管理策略", "努力管理策略", "环境管理策略"], "a": 1, "exp": "此题考查时间管理策略。A.计划策略：属于元认知策略，主要指设置学习目标、浏览材料、产生待解决的问题、分析如何完成任务-——针对做事的顺序规划。B.时间管理策略：小红将侧重记忆的内容安排在晚上学习是根据一天的学习效率变化来决定的，因为她在晚上记忆的效率更高。此题重在区别A、B选项，A选项侧重做事情的规划，B选项侧重时间安排。√C.努力管理策略：为了维持或促进意志努力，而对自已的心理因素进行约束和调整，实现学习目标。D.环境管理策略：主要指对自然条件的调节（如流通的空气、适宜的温度等）和对学习空间的设计（如空间的范围、室内布置、用具摆放等）。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点六|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点六：资源管理策略及其教学", "no": 3, "q": "以下不属于环境管理策略的是（　）", "opts": ["学习时，要注意调节自然条件，如流通的空气、适宜的温度等", "学习时，要设计好学习的空间，如室内布置、用具摆放等", "学习时，要合理安排时间，善于利用零碎时间", "学习时，要善于选择安静、干扰较小的地点，充分利用学习情境的相似性"], "a": 2, "exp": "此题考查环境管理策略。学习的环境管理策略是指善于选择安静、干扰较小的地点学习，充分利用学习情境的相似性；注意调节自然条件；设计好学习的空间；等等。善于利用零碎时间属于时间管理策略。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点六|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点六：资源管理策略及其教学", "no": 4, "q": "大学生利用的学习工具有参考资料、工具书、图书馆、广播电视以及电脑与网络等，这属于（　）", "opts": ["时间管理策略", "努力管理策略", "环境管理策略", "学业求助策略"], "a": 3, "exp": "此题考查学业求助策略。学业求助策略是指学生在学习过程中遇到困难向他人寻求帮助以克服学习困难，提高学习效率的策略。大学生利用参考资料、工具书、图书馆是对文献类工具的求助（这里的“利用图书馆”是利用图书馆的图书资源），利用广播电视、电脑、网络是对多媒体和网络等工具的求助，这属于学业求助策略中的工具利用策略。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点六|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点六：资源管理策略及其教学", "no": 5, "q": "下列选项中，不属于资源管理策略的是（　）", "opts": ["习惯在固定的地方上自习", "相信自己努力就可以学好", "碰到不懂的问题就向老师请教", "常常思考自己的学习方法是否正确"], "a": 3, "exp": "此题考查资源管理策略。资源管理策略是辅助学生管理可用环境和资源的策略。它有助于学生适应环境和调节环境以适应自己的需要，对学生的学习动机起着重要作用，主要包括时间管理策略、努力管理策略、环境管理策略和学业求助策略等。A.习惯在固定的地方上自习：属于环境管理策略。B.相信自已努力就可以学好：属于努力管理策略，这有利于使学习者保持积极的情绪状态，维持或促进意志努力。C.碰到不懂的问题就向老师请教：属于学业求助策略。D.常常思考自己的学习方法是否正确：这是对自已的学习过程进行监控和调节，属于元认知策略。此", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点七|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点七：综合题", "no": 1, "q": "课堂上，教师利用列提纲的形式进行板书，教师采用的策略是（　）", "opts": ["组织策略", "精细加工策略", "计划策略", "资源管理策略"], "a": 0, "exp": "此题考查组织策略。组织策略指整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略。组织策略主要有列提纲、做图解、做表格等方式。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点七|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点七：综合题", "no": 2, "q": "在复习“第二次世界大战”时，小红制作了一张涵盖时间、地点、主要战役和影响的思维导图；小刚则想象自己是一名战地记者，为每场战役写一篇报道。他们分别主要运用了（　）", "opts": ["组织策略、精细加工策略", "精细加工策略、元认知策略", "复述策略、组织策略", "元认知策略、资源管理策略"], "a": 0, "exp": "此题考查学习策略。制作思维导图是对知识进行结构化整理的组织策略；通过角色扮演和创作来增加意义联系，是精细加工策略。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 117}},
  {"id": "kc|edu-psych|xl-06|知识点七|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-06", "chName": "第六章 学习策略及其教学", "sec": "知识点七：综合题", "no": 3, "q": "下列情境中所使用的学习策略对应正确的是（　）", "opts": ["经济economy（依靠农民），救护车ambulance（俺不能死）——复述策略", "读完《红楼梦》这本书，为里面的人物梳理了一个关系图——监察策略", "上课之前，教师提前告知学生这个知识点很重要一—注意策略", "根据事件的轻重缓急程度对一天的事情进行排序-—计划策略"], "a": 2, "exp": "此题考查学习策略。A选项为精细加工策略中的关键词法，B选项为组织策略，C选项为注意策略，D选项为时间管理策略。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 118}},
  {"id": "kc|edu-psych|xl-07|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 1, "q": "传统智力理论。以下不属于传统智力理论的是（　）", "opts": ["斯滕伯格的成功智力理论", "斯皮尔曼的二因素论", "瑟斯顿的群因素论", "吉尔福特的智力三维结构理论"], "a": 0, "exp": "此题考查传统智力理论。传统智力理论以心理测量为基础，认为智力由因素构成，通过因素分析可以探索这些因素，进而认识智力的内核。传统智力理论包括斯皮尔曼的二因素论、瑟斯顿的群因素论、吉尔福特的智力三维结构理论等。斯滕伯格认为传统的智力概念仅仅关注学业方面，过于狭窄，因而他将智力与真实世界相联系，从而解释生活中的各种成功，即成功智力。斯滕伯格的成功智力理论不属于传统智力理论。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 118}},
  {"id": "kc|edu-psych|xl-07|知识点一|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 2, "q": "关于流体智力和晶体智力发展趋势，说法正确的是（　）", "opts": ["随着年龄增长，流体智力越来越高", "随着年龄增长，晶体智力越来越高", "年纪越轻，流体智力越低", "流体智力、晶体智力都与年龄无必然关系"], "a": 1, "exp": "此题考查卡特尔的流体智力和晶体智力理论。美国心理学家卡特尔根据对智力测验结果的分析，将智力分为流体智力和晶体智力。经套课程公众号【研大］（1）流体智力受先天遗传因素影响较大，在青少年之前一直在增长，在30岁左右达到顶峰，随后逐渐衰退，如反应速度、记忆力、计算能力等。流体智力一般是先天的，不太依赖于后天的学习。（2）晶体智力是在实践中形成的能力。这种智力在人的一生中都在增长，如知识的广度、判断力、常识等。晶体智力依赖于后天的学习和经验。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 118}},
  {"id": "kc|edu-psych|xl-07|知识点一|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 3, "q": "根据卡特尔的智力理论分类，长辈常对晚辈说：“我走过的桥比你走过的路还多。”其中暗指的智力类型是（　）", "opts": ["语言智力", "内省智力", "流体智力", "晶体智力"], "a": 3, "exp": "此题考查卡特尔的流体智力和晶体智力理论。A.语言智力：学习和使用语言文字的能力。B.内省智力：认识自己并选择自己生活方向的能力。C.流体智力：受先天遗传因素影响较大，不太依赖于后天的学习。D.晶体智力：在人的一生中都在增长，且依赖于后天的学习和经验，如知识的广度、判断力、常识等。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 118}},
  {"id": "kc|edu-psych|xl-07|知识点一|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 4, "q": "某新手教师和专家教师虽然都讲授同样的知识点，但专家教师在教学过程中引用的词汇、对活动的组织以及教育机智总体来说要好于新手教师，这说明专家教师和新手教师的（）存在一定的差异。（　）", "opts": ["自然观察智力", "流体智力", "晶体智力", "内省智力"], "a": 2, "exp": "此题考查卡特尔的流体智力和晶体智力理论。A.自然观察智力：辨别生物以及对自然世界其他特征敏锐感知的能力。B.流体智力：受先天遗传因素影响较大，达到高峰后开始随年龄的增长而减退，如反应速度、记忆力、计算能力等。C.晶体智力：在人的一生中都在增长，如知识的广度、判断力、常识等。晶体智力依赖于后天的学习和经验。题干中的专家教师和新手教师在后天接受的学习和积累的经验不同，因此最有可能在晶体智力方面存在差异。√D.内省智力：认识自己并选择自己生活方向的能力。·多元智力理论。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点一|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 5, "q": "多元智力理论·美国学者加德纳提出多元智力理论，认为人的心理能力中至少包含8种不同的智力，下面哪一种不属于加德纳概括的8种智力？（　）", "opts": ["语言智力", "想象智力", "人际智力", "音乐智力"], "a": 1, "exp": "此题考查多元智力理论。多元智力理论认为人的心理能力中至少应该包括8种不同的智力：语言智力、逻辑一数学智力、空间智力、音乐智力、肢体一动觉智力、人际智力、内省智力、自然观察智力。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点一|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 6, "q": "个体能正确建构自我，知道如何用这些意识察觉做出适当的行为，并规划、引导自已的人生。这种能力属于加德纳多元智力理论中的（　）", "opts": ["语言智力", "逻辑—数学智力", "空间智力", "内省智力"], "a": 3, "exp": "此题考查多元智力理论。A.语言智力：学习和使用语言文字的能力。B.逻辑一数学智力：数学运算和逻辑思维推理的能力。C.空间智力：凭借知觉辨认距离、判断方向的能力。D.内省智力：能正确建构自我，知道如何利用这些意识察觉做出适当的行为，并规划、引导发展的能力。与题意相符。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点一|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 7, "q": "物理教师描述：“想象你的手上长了一个脓包，你开始挤它（体积减小），挤压时，压强将会增大。你越挤，压强就越大，最后这个脓包破了，脓液洒了你一手！”该教学举例属于加德纳多元智力理论中的（　）", "opts": ["语言智力", "逻辑—数学智力", "空间智力", "自然观察智力"], "a": 2, "exp": "此题考查多元智力理论。A.语言智力：学习和使用语言文字的能力。B.逻辑一数学智力：数学运算和逻辑思维推理的能力。C.空间智力：凭借知觉辨认距离、判断方向的能力。题干中，物理教师的描述为学生提供了比喻或视觉表象，这属于空间智力教学的应用。√D.自然观察智力：辨别生物以及对自然世界其他特征敏锐感知的能力。·成功智力理论·", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点一|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 8, "q": "成功智力理论·斯滕伯格的成功智力理论提出人有三种智力，下列不属于这三种智力的是（　）", "opts": ["分析性智力", "实践性智力", "反思性智力", "创造性智力"], "a": 2, "exp": "此题考查成功智力理论。成功智力理论包括分析性智力、实践性智力、创造性智力。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点一|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点一：智力的基本理论", "no": 9, "q": "一种用以达到人生中的主要目标，在现实生活中真正能产生举足轻重的影响的智力是（　）", "opts": ["情绪智力", "情境智力", "成功智力", "学业智力"], "a": 2, "exp": "此题考查成功智力理论。斯滕伯格用“成功智力”的概念赋予智力新的含义。成功智力是用以达到人生中的主要目标的智力，它能导致个体以目标为导向并采取相应的行动，是对个体的现实生活真正产生举足轻重的影响的智力。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点二：问题及问题解决", "no": 1, "q": "以下属于“问题解决”的是（　）", "opts": ["回忆一个人的名字", "幻想自己是“灰姑娘", "用一个词来造句", "荡秋千"], "a": 2, "exp": "此题考查问题解决。问题解决有以下特点：（1）所解决的是新的问题。（2）在问题解决过程中，个体要重新组织和形成高级规则。（3）问题解决后，能力会得到增长。（4）问题解决涉及认知、情感和行为活动成分。A.回忆一个人的名字：主要涉及记忆提取，不属于“问题解决”。B.幻想自已是“灰姑娘”：这是一种想象活动或角色扮演，并非解决实际问题的过程。C.用一个词来造句：造句时，需要根据语法规则、语境、表达意图，选择合适的句子结构，这需要一定的创造性思维和语言规划，属于“问题解决”。√D.荡秋千：这是外显的技能，不属于“问题解决”。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点二：问题及问题解决", "no": 2, "q": "下列任务中，属于问题解决的是（　）", "opts": ["从原文中画出给定的句子", "多次解决同一道较难的题目", "设计一个节水宣传方案", "问题答案包含在问题之中"], "a": 2, "exp": "此题考查问题解决。A.从原文中画出给定的句子：根据要求进行的简单句子搜索，不属于问题解决。B.多次解决同一道较难的题目：涉及重复练习，不是面对新的问题，不属于问题解决。C.设计一个节水宣传方案：需要运用生活经验与相关知识，思考如何设计出有效的节水宣传方案，这需要创造性地解决问题，涉及复杂的思维过程和认知策略的运用，属于问题解决。√D.问题答案包含在问题之中：属于“答案显而易见”的情况，无须复杂的认知操作即可得出答案。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点二：问题及问题解决", "no": 3, "q": "根据问题的构成要素特点，“求边长为2cm的正方形的面积”属于（　）", "opts": ["结构不良问题", "结构良好问题", "一般性问题", "认知性问题"], "a": 1, "exp": "此题考查结构良好问题。问题按照组织程度分为结构良好问题和结构不良问题。（1）结构良好问题是指那些具有明确的初始状态、目标状态以及解决方法的问题。（2）结构不良问题是指那些没有明确的初始状态、目标状态或解决方法的问题。答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 119}},
  {"id": "kc|edu-psych|xl-07|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点二：问题及问题解决", "no": 4, "q": "下列属于结构不良问题的是（　）", "opts": ["①②④", "②③④", "①③④", "①②③"], "a": 2, "exp": "此题考查结构不良问题。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点三：问题解决的策略方法", "no": 1, "q": "将解决问题的所有可能方案都列举出来，逐一尝试，这种提出解决问题假设的方式被称为（　）", "opts": ["启发式", "算法式", "联想式", "类比式"], "a": 1, "exp": "此题考查问题解决的方法。A.启发式：有时题目非常烦琐，采用算法式途径不可能获得最终的解，这时就得采用启发式。常见的启发式方法有手段一目的分析法、爬山法、逆向反推法、联想法、类比法等。B.算法式：为了达到某一个目标或解决某个问题而采取的程序，与题意相符。√C.联想式：联想解决过的相同或类似问题的思路来解决当前问题的方法，包括相似联想、接近联想、对比联想和因果联想等多种形式。D.类比式：当面对某种问题情境时，个体可以运用类比思维，先寻求与此有些相似的情境的解答。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点三：问题解决的策略方法", "no": 2, "q": "下列有关解决问题的途径，不是启发式方法的是（　）", "opts": ["逆向反推法", "限定词法", "爬山法", "类比思维"], "a": 1, "exp": "此题考查问题解决的方法。依据知识点三第1题解析可知，A、C、D选项属于启发式方法。限定词法是精细加工策略中的一种常用策略。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点三|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点三：问题解决的策略方法", "no": 3, "q": "笛卡尔说：“把我所考察的每一个难题，都尽可能地分成细小的部分，直到可以而且适于加以圆满解决的程度为止。”这与问题解决方法中的（）是一致的。（　）", "opts": ["逆向反推法", "手段一目的分析法", "爬山法", "联想法"], "a": 1, "exp": "此题考查问题解决的方法。A.逆向反推法：从目标状态出发，考虑如何能达到初始状态的问题解决方法，不涉及问题分解。B.手段一目的分析法：把问题划分为一系列子问题，通过逐个解决子问题，最终达到问题解决的目标。与笛卡尔的方法完全一致。√C.爬山法：以渐进的步子向目标状态靠近，是一种向前的工作方式，不强调拆分子问题。D.联想法：通过联想、想象寻找灵感，与问题分解无关。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点三|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点三：问题解决的策略方法", "no": 4, "q": "下列选项中采用了问题解决策略中的爬山法的是（　）", "opts": ["李老师每周与成绩薄弱的小青核对一次学习结果，再根据小青的学情为其布置下周的学习任务", "当证明不出几何题时，王琴就从结论推论已知条件，直到解出几何题", "李华在学会整数的加法交换律之后，可以将其运用到小数的加法交换律中", "刘星在解方程时，将可能的解一一列出，然后逐个进行尝试，直到方程成立"], "a": 0, "exp": "此题考查问题解决的方法。A.该选项属于爬山法，以渐进的步子向目标状态靠近，在不确定手段与目标的差距时应用。√B.该选项属于逆向反推法，是指从目标状态出发，考虑如何达到初始状态。C.该选项属于类比法，当面对某种问题情境时，个体可以运用类比思维，先寻求与此有相似的情境的解答。D.该选项属于算法式，为了达到某一个目标或解决某个问题而采取的程序，通过严格执行算法程序来获得问题的解答。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 1, "q": "关于动机强度与问题解决效率的关系，表述正确的是（　）", "opts": ["动机水平越高，问题解决效率越好", "动机水平越高，问题解决效率越差", "动机水平适中，问题解决效率最好", "动机水平与问题解决效率无必然关系"], "a": 2, "exp": "此题考查影响问题解决的因素。高效率低适宜的动机强度强动机水平动机强度与问题解决效率图动机是促使问题解决的动力因素，对问题解决的思维活动有重要影响。动机的性质和强度会影响问题解决的进程。动机强度与问题解决效率的关系呈“倒U型曲线”，适宜的动机强度最有利于问题的解决。本", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 2, "q": "有的学生在检查自已做完的作业时，总是很难发现其中的错误，但帮助别的同学检查作业时却更容易发现错误，这体现了（）的影响。（　）", "opts": ["原型启发", "酝酿效应", "功能固着", "思维定势"], "a": 3, "exp": "此题考查思维定势。A.原型启发：通过与假设的事物具有相似性的东西，来启发人们解决新问题的途径。B.酝酿效应：又称直觉思维。当一个人长期致力于某一问题而又百思不得其解的时候，如果他暂时停下思考，去做其他事情，由于某个契机突然产生灵感，问题便迎刃而解。C.功能固着：个体在解决问题时往往只看到某种事物的通常功能，而看不到它其他方面可能有的功能。D.思维定势：以最熟悉的方式做出反应的倾向。当问题情境不变时，思维定势对问题的解决有积极的作用，有利于问题的解决；当问题情境发生了变化时，思维定势容易阻碍主体用新方法来解决问题，不利于问题的解决。题干中的例子体现了思维定势的影响。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 3, "q": "在思维训练课中，老师让大家列举纽扣的用处，小丽只想到纽扣可以钉在衣服前面用来扣衣服，却想不到纽扣可以制作成装饰品、点缀衣服等其他用途。这种现象属于（　）", "opts": ["功能迁移", "功能固着", "功能转换", "功能变通"], "a": 1, "exp": "此题考查功能固着。功能固着是指个体在解决问题时往往只看到某种事物的通常功能，而看不到它其他方面可能有的功能。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 4, "q": "以下属于配酿效应的例子的是（　）", "opts": ["看到鸟飞，发明了风筝", "想了好久的问题都想不出答案，干脆不想了，结果过一会儿突然有了解答", "看到别人的办法不错也跟着用", "换一个角度去思考问题"], "a": 1, "exp": "此题考查酝酿效应。A.看到鸟飞，发明了风筝：属于原型启发。B.想了好久的问题都想不出答案，干脆不想了，结果过一会儿突然有了解答：属于配酿效应。√C.看到别人的办法不错也跟着用：观察或模仿，与酝酿效应无关。D.换一个角度去思考问题：有意识地转换思维方式，旨在打破思维定势，与酝酿效应无关。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 5, "q": "从蒲公英的轻轻飘飞受到启发发明出降落伞，这是（　）", "opts": ["酝酿效应", "原型启发", "近因效应", "宽大效应"], "a": 1, "exp": "此题考查原型启发。原型启发是通过与假设的事物具有相似性的东西，来启发人们解决新问题的途径。其中对解决问题具有启发作用的事物或现象叫作原型，如题干中的“蒲公英”就是“降落伞”的原型。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点四|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点四：影响问题解决的因素", "no": 6, "q": "人们观察到猫、狗等动物的爪子在行走时能很好地抓地，因此在设计鞋底时，模仿动物爪子的纹路，制作出了有各种花纹和凸起的防滑鞋底。结合影响问题解决的因素，这属于（　）", "opts": ["酝酿效应", "原型启发", "思维定势", "功能固着"], "a": 1, "exp": "此题考查原型启发。人们从猫、狗等动物的爪子中获得启发，制作出了有各种花纹和凸起的防滑鞋底，这体现了原型启发对问题解决的影响。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 120}},
  {"id": "kc|edu-psych|xl-07|知识点五|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 1, "q": "创造力的核心是（　）", "opts": ["创造性思维", "创造性人格品质", "创造性适应品质", "创造性情意特征"], "a": 0, "exp": "此题考查创造性的基本结构。创造性也叫创造力，它不是单一的能力，是以创造性思维为核心的多种能力的综合。创造性认知品质、创造性人格品质、创造性适应品质是创造性的基本结构。创造性情意特征是创造性人格品质的主要表现。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 2, "q": "不容易出现功能固着的个体在创造性上更具备什么特征？（：（　）", "opts": ["独创性", "灵活性", "流畅性", "新颖性"], "a": 1, "exp": "此题考查创造性思维的特点。A/D.独创性/新颖性：强调想法的新奇、独特、与众不同。虽然功能固着会妨碍产生新颖想法，但直接对应的特征不是它。独创性/新颖性是结果，而灵活性是实现该结果的关键过程。B.灵活性：思维能随机应变，触类旁通，不受固定观念束缚，能从一个类别流畅地转换到另一个类别。这正是克服功能固着的核心能力一一能灵活地重新赋予物体新功能、新意义。√C.流畅性：单位时间内能产生大量想法。功能固着会限制想法数量，但它的本质影响是限制了思维的种类和转换能力。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 3, "q": "达·芬奇设计飞行器时，经过了长期探索。他先后尝试了鸟类扑翼、蝙蝠膜翼和风筝滑翔三种不同的设计方案，最终成功整合各方案的优点创造出新型飞行器。这一过程最能体现创造性思维的（　）", "opts": ["流畅性和综合性", "灵活性和综合性", "独创性和流畅性", "灵活性和流畅性"], "a": 1, "exp": "此题考查创造性思维的特点。（1）流畅性：在短时间内产生的观念数量多、维度少。题干中的三种设计方案属于不同的方向和维度，并未突出体现流畅性。（2）综合性：创造性思维是各种思维的综合。题干描述涉及三种设计方案的整合，突出体现了综合性。（3）独创性：区别于他人的独特想法。题干中，达·芬奇创造的新型飞行器是一个具有独创性的产品。（4）灵活性：在限定时间内产生的观念数量多，维度也多。题干中的三种设计方案属于三个不同角度的思路，体现了灵活性。综合比较，题干更强调创造性思维的综合性、独创性和灵活性，但流畅性不够突出，可排除所有带流畅性的选项。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 4, "q": "下列关于创造性思维的说法，正确的是（　）", "opts": ["小明能在1分钟之内想出30个单人旁的字，说明小明的思维具有灵活性", "一个班里，只有小芳提出把报纸当作珍藏品出售，说明小芳的思维具有独创性", "对同一问题，小红想到6种不同的思路，比其他同学都多，说明小红的思维具有流畅性", "如果一个人思维的流畅性较好，那么他思维的灵活性一定较好"], "a": 1, "exp": "此题考查创造性思维的特点。A.修改：小明能在1分钟之内想出30个单人旁的字，说明小明的思维具有流畅性。B.独创性指产生不寻常的和非常规的反应的能力，B选项小芳的例子符合独创性的定义。√C.修改：对同一问题，小红想到6种不同的思路，比其他同学都多，说明小红的思维具有灵活性。D.修改：当个体思维的流畅性较好时，灵活性不一定好。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 5, "q": "以下不属于创造性作品的是（　）", "opts": ["《共产党宣言》", "《四书集注》", "《哈利·波特》中文译文", "《金刚经》原文手抄稿"], "a": 3, "exp": "此题考查创造性的基本概念。《金刚经》是创造性作品，原文手抄稿只是一种复制。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 6, "q": "华莱士的四阶段论是关于创造性思维过程的最有影响力的理论，该理论认为创造性思维过程是（　）", "opts": ["准备—酝酿—灵感—验证", "准备—生成—探索—验证", "准备—生成—修改—验证", "准备—思考—修订—实践"], "a": 0, "exp": "此题考查华莱士的四阶段论。华莱士的四阶段论认为，创造性思维过程包括准备一沉思（酝酿）灵感或启迪一验证。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 7, "q": "爱迪生在发明电灯的过程中，经历了长时间的实验和尝试。在某个瞬间，他突然想到可以用钨丝作为灯丝，这个想法的闪现使他成功地发明了实用的电灯。这里体现的是华莱士创造性思维过程的（　）", "opts": ["准备阶段", "沉思阶段", "灵感或启迪阶段", "验证阶段"], "a": 2, "exp": "此题考查华莱士的四阶段论。华莱士的创造性思维过程包括准备、沉思、灵感或启迪、验证四个阶段。A.准备：搜集信息的阶段。B.沉思：酝酿阶段。C.灵感或启迪：突然涌现出问题解决办法。题干中，“突然想到可以用钨丝作为灯丝”的想法就属于华莱士创造性思维过程中的灵感或启迪阶段。√D.验证：检验各种解决办法。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 8, "q": "芬克的生成探索模型揭示了“约束”对创造性思维的影响，对此下列说法正确的是（　）", "opts": ["创造性思维无须被某种东西“约束", "约束”只会影响创造性思维的生成阶段", "约束”只会影响创造性思维的探索阶段", "创造性思维的任何发展阶段，都有可能被“约束"], "a": 3, "exp": "此题考查芬克的生成探索模型。芬克的生成探索模型认为创造性思维具体包括生成阶段和探索阶段。此外，该模型假设对于最终结果的“约束”可以发生在生成阶段或探索阶段的任何时候。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 9, "q": "下列能够影响创造性发展的因素中，表述正确的是（　）", "opts": ["智力、年龄、情绪与认知风格", "知识、性别、情绪与认知风格", "个性、年龄、情绪与认知风格", "智力、动机、情绪与认知风格"], "a": 3, "exp": "此题考查影响创造性发展的主要因素。影响创造性发展的个人因素有智力、知识、个性、动机、情绪与认知风格。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|10", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 10, "q": "关于情绪对个体创造性发展的影响，描述正确的是（　）", "opts": ["高兴可以促进创造性思维的发展", "愤怒会抑制创造性思维的发展", "对于场独立型的个体，高兴情绪会促进人的创造性思维", "对于场依存型的个体，愤怒情绪会促进人的创造性思维"], "a": 0, "exp": "此题考查影响创造性发展的主要因素。愤怒可以促进创造性思维的发展，B选项说法错误。对于场独立型的个体，愤怒情绪会促进人的创造性思维，C选项说法错误。对于场依存型的个体，高兴情绪会促进人的创造性思维，D选项说法错误。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 121}},
  {"id": "kc|edu-psych|xl-07|知识点五|11", "bank": "kc", "subj": "edu-psych", "ch": "xl-07", "chName": "第七章 问题解决能力与创造性的培养", "sec": "知识点五：创造性及其培养", "no": 11, "q": "进行思考和讨论时，先尽可能想出所有可能的方法，最后再集中对这些方法加以评判，这种创造性思维训练方法被称为（　）", "opts": ["脑激励法", "分合法", "自由联想技术", "定向联想法"], "a": 0, "exp": "此题考查创造性思维的培养方法。A.脑激励法（头脑风暴法）：基本做法是教师先提出问题，然后鼓励学生畅所欲言，寻找尽可能多的答案，不必考虑该答案是否正确，教师也不做评论，一直到所有可能想到的答案都提出来为止。√B.分合法：“使熟悉的事物变得新奇”（即学生用新颖而富有创意的观点去重新了解旧事物）和“使新奇的事物变得熟悉”（即学生先从熟悉的概念人手，通过分析法和类比法来尽快熟悉陌生事物）。C.自由联想技术：教师提供一个刺激，让学生以不同的方式自由联想，自由地提出各种不同的想法及观念。D.定向联想法：联想范围受到一定限制，并非完全自由发散。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 122}},
  {"id": "kc|edu-psych|xl-08|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点一：社会规范学习的过程与条件", "no": 1, "q": "个体对社会规范的接受是逐步完成的，是一个由低到高、从外到内的社会价值内化过程，应当依次经历（　）", "opts": ["遵从一内化—认同", "遵从—认同一内化", "认同一遵从一内化", "内化一认同—遵从"], "a": 1, "exp": "此题考查社会规范学习的过程与条件。社会规范学习总结表内化阶段遵从认同社会规范成为个体的价值信念含义个体自愿接受社会规范个体对社会规范遵照执行自觉性、主动性、稳定性高度的自觉性、主动性及坚定性特点盲目性、被动性、工具性、情境性条件深化，外→内高级地位初级依据社会规范学习总结表可知，个体对社会规范的接受应当依次经历遵从一认同一内化。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 122}},
  {"id": "kc|edu-psych|xl-08|知识点一|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点一：社会规范学习的过程与条件", "no": 2, "q": "某城市推行垃圾分类政策后，有的居民经过环保知识学习，真正认同垃圾分类的生态价值，即使无人监督也坚持分类，甚至还会主动向邻居宣传其重要性。根据社会规范学习的过程，上述行为表明个体处于社会规范的（　）", "opts": ["依从阶段", "认同阶段", "内化阶段", "遵从阶段"], "a": 2, "exp": "此题考查社会规范学习的过程与条件。（1）依从：也称遵从，包括从众和服从。从众指主体对于某种行为要求的依据缺乏必要的认识，跟随他人行动的现象。服从强调外部压力（如惩罚、奖励），无内在接受。例如，司机因害怕罚款而遵守交通规则。（2）认同：包括偶像认同和价值认同。偶像认同强调主体试图与榜样一致，即对榜样的遵从或模仿。价值认同强调个体因认识到规范本身的意义而发生的对规范的遵从现象。例如，司机认识到遵守交通规则是安全行驶的保障，便自觉执行交通规则。（3）内化：个体的规范行为是由社会规范的价值信念所驱动的。例如，司机认为遵守交通规则是公民责任，即使无监控也坚持遵守。这便是司机基于对交通规则本身的价值信念而进行的遵从。题干描述符合内化阶段的表现。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 122}},
  {"id": "kc|edu-psych|xl-08|知识点一|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点一：社会规范学习的过程与条件", "no": 3, "q": "“随波逐流”“人云亦云”属于（　）", "opts": ["认同现象", "旁观者效应", "服从现象", "从众现象"], "a": 3, "exp": "．此题考查从众现象。社会规范的依从包括从众和服从。从众指主体对于某种行为要求的依据缺乏必要的认识，跟随他人行动的现象。“随波逐流”“人云亦云”都是比喻没有坚定的立场，缺乏判断是非的能力，只能随着别人走，属于从众现象。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点二：态度的学习", "no": 1, "q": "下列哪项不属于态度的心理结构？（　）", "opts": ["认知成分", "情感成分", "行为意向成分", "行为成分"], "a": 3, "exp": "此题考查态度的心理结构。态度是人对客观对象、现象是否符合主体需要而产生的心理倾向。态度的心理结构包括认知成分、情感成分和行为意向成分。行为成分不属于心理层面。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点二：态度的学习", "no": 2, "q": "影响态度形成与改变的条件可分为主观条件和客观条件，下列哪项属于主观条件？（　）", "opts": ["外部强化", "榜样人物", "信息的可信度", "认知失调"], "a": 3, "exp": "此题考查影响态度形成与改变的条件。当个体处于认知失调状态时，就会努力改变自已的观念或信念来求得新的平衡。个体的观念或信念属于主观条件。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点二：态度的学习", "no": 3, "q": "当教师在帮助学生改变态度时，其做法正确的是（　）", "opts": ["对持赞同态度的人，应提供双面证据", "对持反对态度的人，应提供单面证据", "对低年级的学生，以情动人更见效果", "对待大学生，只需做好说理论证"], "a": 2, "exp": "此题考查态度的改变。对持赞同态度的人，应提供单面证据；对持反对态度的人，应提供双面证据，A、B选项错误。对待大学生，需先以情动人，然后用充分的材料进行说理论证，说服效果才能长久，D选项错误。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点二：态度的学习", "no": 4, "q": "关于态度的描述，不正确的是（　）", "opts": ["态度是通过学习形成的，而不是天生的", "个体所持的任一态度都是指向某一具体对象的", "态度往往能从外部直接观察到", "个体对某一事物所形成的态度，是对各种具体对象的态度概括化的结果"], "a": 2, "exp": "此题考查态度的性质。A.态度是学习的结果，并非先天本能。B.态度具有对象性，是针对某一具体对象产生的，离开一定的对象，态度就无法孤立地存在。C.修改：态度的行为倾向可以通过外显行为间接推测，但态度本身是内部心理状态，无法从外部直接观察到。此题为选非题。√D.态度具有概括性，个体对某一类事物的整体态度，是对该类事物中具体对象的态度概括化的结果。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 1, "q": "皮亚杰对道德认知进行研究的方法是（　）", "opts": ["道德两难故事", "守恒实验", "沙盘游戏", "对偶故事法"], "a": 3, "exp": "此题考查皮亚杰的对偶故事法。A.道德两难故事：科尔伯格开创的研究道德发展问题的重要研究方法。B.守恒实验：皮亚杰研究认知发展的方法，不是专门针对道德认知的。C.沙盘游戏：心理治疗中的一种方法，不是皮亚杰的研究方法。D.对偶故事法：皮亚杰独创的临床研究法所使用的手段，用于研究儿童道德认知发展。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 2, "q": "因为帮母亲做家务打碎了15只杯子和因为偷吃东西打碎了1只杯子，如果让某儿童判断以上两种情况中哪种情况过错更大，儿童的回答是前者的过错更大，因为打碎的杯子更多。根据皮亚杰的道德认知发展理论，该儿童所处的发展阶段为（　）", "opts": ["前道德阶段", "无律阶段", "他律道德阶段", "自律道德阶段"], "a": 2, "exp": "此题考查皮亚杰的道德认知发展理论。根据皮亚杰的道德认知发展理论，在他律道德阶段，儿童的道德认知一般是服从外部规则，接受权威指定的规范，他们只根据行为后果判断对错，而不考虑行为的动机。题干中，儿童根据打碎杯子的多少来判断后果，属于他律道德阶段。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 3, "q": "在道德品质发展的研究中，科尔伯格等心理学家的研究重点是（　）", "opts": ["道德认知", "道德情感", "道德意志", "道德行为"], "a": 0, "exp": "此题考查科尔伯格的道德两难故事法。科尔伯格开创的道德两难故事法，通过引起儿童的道德认知冲突，以讨论的方式解决认知的冲突，促进儿童的道德发展。因此，科尔伯格等心理学家研究的重点是儿童的道德认知。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 4, "q": "科尔伯格的道德两难故事采用（）的方法培养道德认知。（　）", "opts": ["言语说服", "道德概念分析", "小组道德讨论", "移情性理解"], "a": 2, "exp": "此题考查科尔伯格的道德两难故事法。小组道德讨论是指让学生在小组中就某个有关道德的典型事件进行讨论，以提高他们的道德判断水平，如科尔伯格的道德两难故事。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 5, "q": "在剑桥中学，学生每周要参加一次两小时的会议，大家共同讨论，提出管理学校的各种规章，并以投票方式决定是否采用。这种教育方法是（　）", "opts": ["讨论法", "模拟法庭法", "公正团体法", "模拟市政法"], "a": 2, "exp": "此题考查科尔伯格的公正团体法。A.讨论法：仅强调师生或生生间的交流探讨，无民主决策、制定并执行集体规则的核心要求。B.模拟法庭法：与制定学校规章的场景无关，排除。C.公正团体法：核心是民主管理，即反对学校权威式的传统管理方式，主张各校应该由学生自已组建一个全体会议（也叫公正团体），在会议上大家对各种管理方式进行民主讨论和决定，最终促使学校的规章制度生效。题干中，学生每周参加两小时会议，集体讨论并投票决定学校规章，这体现了科尔伯格提出的“公正团体法”的核心特征。√D.模拟市政法：题干明确是“管理学校的各种规章”，并非模拟社会市政，排除。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 6, "q": "一个经常违纪的学生被调到一个风气良好的班级后，发现该班出现违纪的学生会受到严厉的惩罚，其违纪行为暂时很少表现出来。这体现了观察学习的（　）", "opts": ["习得效应", "情绪唤起效应", "抑制效应", "反应促进效应"], "a": 2, "exp": "此题考查班杜拉的社会学习理论。A.习得效应：通过观察习得新行为。B.情绪唤起效应：看到他人表达的情感，在观察者身上容易唤起类似的情感。C.抑制效应：观察者看到他人因不良行为受到社会遣责，会暂时抑制受到遣责的不良行为。题干中，学生因为看到惩罚而抑制了原有行为，所以是抑制效应。√D.反应促进效应：观察者通过观看他人行为引发其行为库中已有的反应。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 7, "q": "妮套课程公众号【研大]关于道德认知的培养方法，下列说法错误的是（　）", "opts": ["道德两难故事有助于提高儿童的道德认知水平", "对道德概念进行分析时，需要结合大量的真实情境", "对低年级的学生，在言语说服时更适合提供正反两方面的论据", "对高年级的学生，逻辑性强的说服内容更为有效"], "a": 2, "exp": "．C理解+综合题此题考查道德认知的培养方法。C选项中，低年级的学生理解能力较差，所以更适合只提供正面论据，以及具有强烈情感色彩的说服内容。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 123}},
  {"id": "kc|edu-psych|xl-08|知识点三|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 8, "q": "以下有关道德情感的描述，不正确的是（　）", "opts": ["道德情感可以调节、控制人的道德行为", "道德情感可以通过引发羞愧感来培养", "道德情感是先于道德认识产生的一种内心体验", "道德情感可以激发、引导人的道德认识"], "a": 2, "exp": "此题考查道德情感。道德情感是伴随着道德认识而产生的一种内心体验。此题为选非题，因此，答案选C。深联系微信193163788日", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点三|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 9, "q": "班主任为了维护班级纪律，决定让平时调皮的学生担任纪律委员，于是该学生改掉了调皮的习惯，班级纪律也有了很大的改善。该班主任使用的品德培育方式是（　）", "opts": ["言语说服", "道德讨论", "角色扮演", "引发羞愧感"], "a": 2, "exp": "此题考查品德培养的方法。角色扮演是让个人暂时置身于他人的社会位置，并按这一位置所要求的方式和态度行事，以增进个人对他人的社会角色及自身原有角色的理解，从而更有效地扮演自已的角色。题干中，调皮的学生在担任纪律委员时，就会按照这一位置所要求的方式和态度行事，增进该学生对维护纪律的认识，从而改变了他的调皮行为，更好地扮演纪律委员的角色。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点三|10", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点三：品德的学习", "no": 10, "q": "品德不良学生的转化一般要经历的阶段是（　）", "opts": ["执—醒悟—改变", "醒悟一再犯—顿悟", "醒悟—转变一自新", "转变一自新—醒悟"], "a": 2, "exp": "此题考查品德不良学生的转化。品德不良学生的转化要经历一个由量变到质变的过程，这个转化过程大体可以划分为醒悟、转变与自新三个阶段。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点四：移情的四种表现", "no": 1, "q": "某班级有同学因学习太累想要弃学回家，李老师告诉他：“你的想法我曾经也有，这种想法是很正常的，当你学累的时候，可以适当给自已放个假，让自已放松放松。”李老师与学生沟通过程中使用的技巧是（　）", "opts": ["移情", "言语说服", "角色扮演", "情绪唤起效应"], "a": 0, "exp": "此题考查移情。A.移情：对事物进行判断和决策之前，将自已处在他人位置考虑他人的心理反应，理解他人的态度和情感的能力。题干中，李老师通过理解学生学习的处境，去感受学生的情绪体验，建议该学生给自已放个假，这一做法考虑了学生可能需要的帮助，体现了移情。√B.言语说服：通过讲道理来使学生接受一定的道德观念和道德准则。题干中，李老师并没有直接进行说服教育。C.角色扮演：让个人暂时置身于他人的社会位置，并按这一位置所要求的方式和态度行事，以增进个人对他人的社会角色及自身原有角色的理解，从而更有效地扮演自己的角色。题干未体现。D.情绪唤起效应：看到他人表达的情感，在观察者身上容易唤起类似的情感，与题意不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点四：移情的四种表现", "no": 2, "q": "当一个人仅凭一张没有背景信息的静态照片，就能判断出照片中的人物是“惊讶”还是“害怕”时，他主要依赖的心理过程是（　）", "opts": ["表情识别", "情境理解", "情绪追忆", "角色代人"], "a": 0, "exp": "此题考查移情的四种表现。A.表情识别：通过对方的表情来判断对方的态度、需求和情绪、情感体验，可借助照片、图片等来理解他人情绪。题干中，仅凭一张没有背景信息的静态照片就能判断照片中人物的情绪，这属于表情识别。√B.情境理解：理解当事人的处境，从他的处境去感受他的情绪体验，考虑他需要的帮助。这可以采用故事讨论的形式，分析故事中人物的处境和体验。C.情绪追忆：针对一定的情境，通过言语提示唤醒与此有关的感受，并对这种情绪体验产生的情境、原因、事件进行追忆，加强情绪体验与特定情境之间的联系。D.角色代入：角色扮演的核心心理过程，即把自已放到别人的位置上，体验对方的情绪、想法、立场。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点四|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点四：移情的四种表现", "no": 3, "q": "在“感恩教育”活动中，老师引导学生们静心回想“父母或他人为自已做过的最感动的一件事”，并通过分享唤醒内心的感激之情。这一过程对学生品德发展的关键作用在于运用了（　）", "opts": ["表情识别", "情境理解", "情绪追忆", "角色扮演"], "a": 2, "exp": "此题考查移情的四种表现。情绪追忆指教师针对一定的情境，通过言语提示唤醒学生与此有关的感受，并对这种情绪体验产生的情境、原因、事件进行追忆，加强情绪体验与特定情境之间的联系。题干中，“静心回想父母或他人为自己做过的最感动的一件事”“唤醒内心的感激之情”，正是运用了情绪追忆这一方法。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-psych|xl-08|知识点四|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-08", "chName": "第八章 社会规范学习、态度与品德发展", "sec": "知识点四：移情的四种表现", "no": 4, "q": "教师在讲授杜甫所作的《茅屋为秋风所破歌》时，生动地描绘了作者的茅屋被秋风所破以致全家遭雨淋的痛苦经历，这运用了以下哪种方法？（　）", "opts": ["表情识别", "情境理解", "情绪追忆", "角色扮演"], "a": 1, "exp": "此题考查移情的四种表现。情境理解指教师理解当事人的处境，从他的处境去感受他的情绪体验，考虑他需要的帮助。这可以采用故事讨论的形式，让学生分析故事中人物的处境和体验。题干中，教师生动描绘茅屋被秋风所破、全家遭雨淋的经历，本质是在构建、呈现具体情境，帮助学生理解杜甫当时的处境与情感，属于情境理解。因此，答案选B。深联系微信193163788日", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 124}},
  {"id": "kc|edu-principle|ep-01|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 1, "q": "从教育的陈述方式看，“教育决定未来，知识改变命运”属于（　）", "opts": ["教育口号", "教育隐喻", "教育信念", "教育定义"], "a": 0, "exp": "此题考查教育口号。A.教育口号：通常是非系统化、简练、明晰、通俗易懂的，且富有宣传和鼓励作用的公共言语。题干中的句子意在宣传教育的重要性，鼓励群众通过学习改变未来和命运。√B.教育隐喻：运用比喻方式来解释教育事实、描述教育理想。C.教育信念：在长期的教育实践与理论学习中，教育者形成的对教育本质、价值、目标及实践方式的稳定的价值判断与体系。D.教育定义：也称教育术语，指对于一种事物的本质特征或一个概念的内涵和外延的确切而简要的说明。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 2, "q": "陶行知说：“教育就像喂鸡一样。先生强迫学生去学习，把知识硬灌给他，他是不情愿学的。即使学也是食而不化，过不了多久，他还是会把知识还给先生的。”根据教育的陈述类型，这种表达属于（　）", "opts": ["教育术语", "教育隐喻", "教育概念", "教育口号"], "a": 1, "exp": "此题考查教育的陈述类型。A.教育术语：也称教育定义，指对于一种事物的本质特征或一个概念的内涵和外延的确切而简要的说明。B.教育隐喻：运用比喻方式来解释教育事实、描述教育理想。题干中，陶行知把教育比喻成喂鸡，这种表述属于教育隐喻。√C.教育概念：广义的教育指一切促进人发展的教育活动，狭义的教育主要指学校教育。D.教育口号：通常是非系统化、简练、明晰、通俗易懂的，且富有宣传和鼓励作用的公共言语。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 3, "q": "根据教育陈述的类型，“以爱为基，以教为桥，守护儿童，通向未来”属于（　）", "opts": ["教育隐喻+教育口号", "教育定义+教育隐喻", "教育口号+教育定义", "教育规定+教育口号"], "a": 0, "exp": "此题考查教育的陈述类型。（1）题干表述将爱比作基石、根基，把教育比作桥梁，属于教育隐喻。（2）题干表述属于简短、富有感染力的口号，属于教育口号。（3）题干表述未提供具体描述，不属于教育定义。（4）题干表述未提及是谁说的话或者哪本书里的始终如一的定义，不属于教育规定，且题干要求根据教育陈述的类型寻找答案，“教育规定”的说法不符合题意。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 4, "q": "“教师不再是直接给学生金子，而是把挖掘宝藏的钥匙给学生。”从教育的陈述类型和谢弗勒对教育定义的方式看，这句话属于（　）", "opts": ["教育隐喻+纲领性定义", "教育隐喻+描述性定义", "教育口号+纲领性定义", "教育口号+描述性定义"], "a": 0, "exp": "此题考查教育的陈述类型和谢弗勒对教育定义的分类。结合题干，这句话属于教育隐喻，排除C、D选项。题干的意思是教师不是将知识直接灌输给学生，而是应该启发学生，“把挖掘宝藏的钥匙给学生”包含了“是”和“应该”的成分，属于纲领性定义。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 5, "q": "“教育是在一定的社会背景下发生的促使个体社会化和社会个性化的实践活动。”这一陈述属于（　）", "opts": ["教育口号", "教育隐喻", "教育信念", "教育定义"], "a": 3, "exp": "此题考查教育的陈述类型。教育定义旨在揭示教育的本质、内在意涵与外部特征，帮助人们认识和理解“教育是什么”，一般具有清晰的含义及较为明确的规定。结合题干，这属于教育定义。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 6, "q": "从教育的定义看，“教育是促进受教育者各方面发展的过程，它最终极的目的应是帮助受教育者习得道德和价值的过程”，这是（　）", "opts": ["描述性定义", "规定性定义", "纲领性定义", "正式性定义"], "a": 2, "exp": "此题考查纲领性定义。A.描述性定义：对被定义对象的适当描述或对如何使用定义对象的适当说明。B.规定性定义：作者自已所创制的定义，其内涵在作者的某种话语语境中始终是统一的。C.纲领性定义：一种关于定义对象“应该是什么”的界定。“教育是.”“最终极的目的应是.”表明这是一种关于定义对象应该是什么的界定。其主要功能倾向于陈述一种道德规范，它包含“是”和“应该”两种成分。√D.正式性定义：干扰项。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 7, "q": "根据谢弗勒对教育定义的分类，下列三个表述依序分别属于（并为社会做出贡献（　）", "opts": ["规定性定义、纲领性定义、描述性定义", "规定性定义、描述性定义、纲领性定义", "描述性定义、规定性定义、纲领性定义", "描述性定义、纲领性定义、规定性定义"], "a": 1, "exp": "此题考查谢弗勒对教育定义的分类。（1）规定性定义：作者自已所创制的定义，其内涵在作者的某种话语语境中始终如一。①是许慎的个人观点，在《说文解字》中始终遵循，属于规定性定义。（2）描述性定义：一种关于定义对象“是什么”的描述。②是对“教育是什么”的描述，属于描述性定义。（3）纲领性定义：一种关于定义对象“应该是什么”的界定。③中有“旨在”这一关键词，所有“旨在”都属于“应该是什么”的说明，故③属于纲领性定义。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 131}},
  {"id": "kc|edu-principle|ep-01|知识点一|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点一：谢弗勒对教育定义的分类", "no": 8, "q": "蔡元培认为：“教育是帮助被教育的人，给他能发展自已的能力，完成他的人格，于人类文化上能尽一分子的责任，不是把被教育的人造成一种特别器具。”按照美国教育哲学家谢弗勒的三种教育的定义方式，这种定义属于（　）", "opts": ["操作性定义", "描述性定义", "纲领性定义", "解释性定义"], "a": 2, "exp": "此题考查纲领性定义。特别器具”，与旧观念形成了一种鲜明对比，所以这句话属于纲领性定义。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 1, "q": "教育活动与其他社会活动的显著区别是（　）", "opts": ["有目的地培养人", "育人过程具有文化性", "综合性的社会实践活动", "促进人的全面发展"], "a": 0, "exp": "此题考查教育的本质。教育是有目的地培养人的社会活动，这是教育活动与其他社会活动的根本区别。B、C、D选项，教育活动和社会活动都具有这些特点。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 2, "q": "某教育公司为员工开设“人工智能教育应用”专题培训课程，这属于（　）", "opts": ["非正式教育", "非正规教育", "正规教育", "非制度化教育"], "a": 1, "exp": "此题考查非正规教育。A.非正式教育：日常生活中无组织的学习（如家庭、社交中的潜移默化)。题干中的专题培训课程是有计划、有组织的，排除该选项。B.非正规教育：正规教育之外的有组织、有计划的非学历教育（如企业培训、社区课程）。题干中的专C.正规教育：系统化的学历教育（如学校教育）。题干中的专题培训课程不授予学历证书，排除该选项。D.非制度化教育：非正式教育的别称。排除该选项。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}}
]);
